INSERT INTO sys_export_job_payload (id, job_id, payload_type, payload_json, content_sha256)
SELECT #{payload.id}, job.id, #{payload.payloadType}, #{payload.payloadJson}, #{payload.contentSha256}
FROM sys_export_job job
WHERE job.id = #{payload.jobId} AND job.requester_id = #{requesterId}
  AND job.student_id = #{studentId} AND job.status = 'QUEUED' AND job.version_no = 0
